    public int var { get; set; }
    int IFace1.Func() {
        this.var = 1;
        return this.var++;
    }
    int IFace2.Func() {
        this.var = 1;
        return ++this.var;
    }
}
class Program {
    static void Main(string[] args) {
        ClassExam obj = new ClassExam();
        int var1 = ((IFace1)obj).Func();
        int var2 = ((IFace2)obj).Func();
